export function splitBlocks(html: string): DraftBlock[] {
  if (typeof window === "undefined") return [];
  const doc = new DOMParser().parseFromString(html, "text/html");
  return Array.from(doc.body.children).map((el, i) => ({
    id: `b${i}`,
    html: el.outerHTML,
  }));
}

